[CmdletBinding()]param()
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$tmp=Join-Path $env:TEMP ('spectra-ops-contract-'+[guid]::NewGuid().ToString('N'));New-Item -ItemType Directory $tmp|Out-Null
try{foreach($profile in @('implementation','support-only')){$a=Join-Path $tmp "$profile-a";$b=Join-Path $tmp "$profile-b";& (Join-Path $PSScriptRoot 'New-SyntheticCutoverOperationsHandover.ps1') -Destination $a -Profile $profile;& (Join-Path $PSScriptRoot 'New-SyntheticCutoverOperationsHandover.ps1') -Destination $b -Profile $profile;$fa=Join-Path $a 'cutover-operations-handover.json';$fb=Join-Path $b 'cutover-operations-handover.json';if((Get-FileHash $fa).Hash-ne(Get-FileHash $fb).Hash){throw 'OPS_GENERATOR_NOT_DETERMINISTIC'};$before=(Get-FileHash $fa).Hash;& (Join-Path $PSScriptRoot 'Test-CutoverOperationsHandover.ps1') -Path $a;if((Get-FileHash $fa).Hash-ne$before){throw 'OPS_VALIDATOR_MUTATED_SOURCE'}};Write-Host 'PASS: Beide Cutover-/Betriebsprofile sind deterministisch und read-only.'}finally{if(Test-Path $tmp){Remove-Item $tmp -Recurse -Force}}
